using Xunit;

public class U10_AlarmsTest
{
    [Fact]
    public void HighLeakageAlarm_ActiveWhenAverageLeakageOverXSecondsIsGreaterThan3LPerMin()
    {
        // Arrange
        var averageLeakage = 4L;
        var threshold = 3L;
        var duration = TimeSpan.FromSeconds(X); // Replace X with the actual duration

        // Act
        var alarm = new HighLeakageAlarm();
        alarm.ComputeAlarm(averageLeakage, duration);

        // Assert
        Assert.True(alarm.IsActive);
    }

    [Fact]
    public void HighLeakageAlarm_HighPriority()
    {
        // Arrange
        var alarm = new HighLeakageAlarm();

        // Assert
        Assert.Equal(AlarmPriority.High, alarm.Priority);
    }

    [Fact]
    public void InvoluntaryShutdownAlarm_ContinuousToneAlarm()
    {
        // Arrange
        var alarm = new InvoluntaryShutdownAlarm();

        // Assert
        Assert.True(alarm.IsContinuousTone);
    }

    [Fact]
    public void InvoluntaryShutdownAlarm_SoundToneForAtLeast2Min()
    {
        // Arrange
        var duration = TimeSpan.FromMinutes(2);

        // Act
        var alarm = new InvoluntaryShutdownAlarm();
        alarm.EmitSound(duration);

        // Assert
        Assert.True(alarm.SoundEmitted);
        Assert.Equal(duration, alarm.SoundDuration);
    }

    [Fact]
    public void AlarmSubsystem_ContinuousToneAlarmsSupported()
    {
        // Arrange
        var alarmSubsystem = new AlarmSubsystem();

        // Assert
        Assert.True(alarmSubsystem.SupportsContinuousToneAlarms);
    }

    [Fact]
    public void Gui_DetectsLossOfACMains()
    {
        // Arrange
        var sensor = new ACMainsPowerLossSensor();
        sensor.DetectPowerLoss();

        // Assert
        Assert.True(sensor.PowerLossDetected);
    }

    [Fact]
    public void Gui_ConnectedToACMainsPowerLossSensor()
    {
        // Arrange
        var gui = new Gui();

        // Assert
        Assert.NotNull(gui.ACMainsPowerLossSensor);
    }

    [Fact]
    public void ACMainsPowerLossAlarm_MediumPriority()
    {
        // Arrange
        var alarm = new ACMainsPowerLossAlarm();

        // Assert
        Assert.Equal(AlarmPriority.Medium, alarm.Priority);
    }
}
